## ----fig-counts, echo=FALSE, eval=TRUE, cache=TRUE, fig.cap=paste0("Private household address counts (", cfmt("addr_type1"), ") aggregated to H3 hexagons at resolution~8 (left) and to neighborhoods (right) for Lauro de Freitas, Bahia."), fig.alt="Two side-by-side choropleth maps of Lauro de Freitas. The left map shows private household address counts aggregated to H3 hexagons at resolution 8; the right map shows the same counts aggregated to neighborhoods. Both maps use a green-to-yellow colour scale where darker green indicates lower counts and bright yellow indicates higher counts.", fig.width=10, fig.height=5, out.width="100%"----
library(geobr)
library(ggplot2)
library(sf)
library(dplyr)
library(patchwork)
library(paletteer)

# Lauro de Freitas boundary
muni_ldf <- geobr::read_municipality(code_muni = 2919207, year = 2020,
                                     showProgress = FALSE)

# Neighborhoods of Lauro de Freitas
nei <- geobr::read_neighborhood(year = 2022, showProgress = FALSE) |>
  dplyr::filter(name_muni == "Lauro de Freitas")

# Address counts per H3 hexagon at resolution 8
hex8 <- cnefetools::cnefe_counts(
  code_muni     = 2919207,
  h3_resolution = 8,
  verbose       = FALSE
)

# Address counts per neighborhood
poly_counts <- cnefetools::cnefe_counts(
  code_muni    = 2919207,
  polygon      = nei,
  verbose      = FALSE
)

p1 <- ggplot(hex8) +
  geom_sf(aes(fill = addr_type1), color = NA)+
  paletteer::scale_fill_paletteer_c("grDevices::ag_GrnYl",
                                    direction = 1, 
                                    name = "Count")+
  labs(title = "H3 resolution 8") +
  theme_void() +
  theme(plot.title = element_text(hjust = 0.5, size = 11),
        legend.position = "right",
        plot.background = element_rect(fill = "white", color = NA))

p2 <- ggplot() +
  geom_sf(data = poly_counts, aes(fill = addr_type1), color = "white",
          linewidth = 0.2) +
  paletteer::scale_fill_paletteer_c("grDevices::ag_GrnYl",
                                    direction = 1, 
                                    name = "Count")+
  labs(title = "Neighborhoods") +
  theme_void() +
  theme(plot.title = element_text(hjust = 0.5, size = 11),
        legend.position = "right",
        plot.background = element_rect(fill = "white", color = NA))

p1 + p2


