## ----fig-bgbi, echo=FALSE, eval=TRUE, cache=TRUE, fig.cap="Bidirectional Global-centered Balance Index (BGBI) for Lauro de Freitas, Bahia, aggregated to H3 hexagons at resolution~8 (left) and to neighborhoods (right). Green cells indicate a local residential share above the citywide average ($p_i > P$); pink cells indicate non-residential dominance ($p_i < P$); white cells are near the citywide baseline.", fig.alt="Two side-by-side choropleth maps of Lauro de Freitas showing the BGBI index. The left map aggregates to H3 hexagons at resolution 8 and the right map aggregates to neighborhoods. Green areas indicate a local residential share above the citywide average, pink areas indicate non-residential dominance, and white or neutral areas are near the citywide baseline.", fig.width=10, fig.height=5, out.width="100%"----
library(geobr)
library(ggplot2)
library(sf)
library(dplyr)
library(patchwork)

# Lauro de Freitas boundary
muni_ldf <- geobr::read_municipality(code_muni = 2919207, year = 2020,
                                     showProgress = FALSE)

# Neighborhoods of Lauro de Freitas
nei <- geobr::read_neighborhood(year = 2022, showProgress = FALSE) |>
  dplyr::filter(name_muni == "Lauro de Freitas")

# BGBI per H3 hexagon at resolution 8
lumi_hex <- cnefetools::compute_lumi(
  code_muni     = 2919207,
  h3_resolution = 8,
  verbose       = FALSE
)

# BGBI per neighborhood
lumi_poly <- cnefetools::compute_lumi(
  code_muni    = 2919207,
  polygon      = nei,
  verbose      = FALSE
)

tropic_colors <- paletteer::paletteer_c("grDevices::Tropic", n = 256, direction = -1)

p1 <- ggplot(lumi_hex) +
  geom_sf(aes(fill = bgbi), color = NA, linetype = 1) +
  geom_sf(data = dplyr::filter(lumi_hex, is.na(bgbi)),
          aes(linetype = "No data (NA)"),
          fill = NA, color = NA) +
  scale_fill_gradientn(
    colours  = tropic_colors,
    limits   = c(-1, 1),
    na.value = "gray40",
    name     = "BGBI"
  ) +
  scale_linetype_manual(
    values = 0, name = NULL,
    guide  = guide_legend(
      override.aes = list(fill = "grey40", color = NA, linewidth = 0)
    )
  ) +
  labs(title = "H3 resolution 8") +
  theme_void() +
  theme(plot.title = element_text(hjust = 0.5, size = 11),
        legend.position = "right",
        legend.box = "vertical",
        plot.background = element_rect(fill = "white", color = NA))

p2 <- ggplot() +
  geom_sf(data = lumi_poly, aes(fill = bgbi),
          color = "white", linewidth = 0.2, linetype = 1) +
  geom_sf(data = dplyr::filter(lumi_poly, is.na(bgbi)),
          aes(linetype = "No data (NA)"),
          fill = NA, color = NA) +
  scale_fill_gradientn(
    colours  = tropic_colors,
    limits   = c(-1, 1),
    na.value = "grey80",
    name     = "BGBI"
  ) +
  scale_linetype_manual(
    values = 0, name = NULL,
    guide  = guide_legend(
      override.aes = list(fill = "grey80", color = "white", linewidth = 0.2)
    )
  ) +
  labs(title = "Neighborhoods") +
  theme_void() +
  theme(plot.title = element_text(hjust = 0.5, size = 11),
        legend.position = "right",
        legend.box = "vertical",
        plot.background = element_rect(fill = "white", color = NA))

p1 + p2


