# Interpolate population in private and collective households to H3 hexagons
hex_pop <- tracts_to_h3(
  code_muni     = 2919207,
  h3_resolution = 9,
  vars          = c("pop_ph", "pop_ch"),
  cache         = TRUE,
  verbose       = TRUE
)

# Interpolate to user-supplied polygons (e.g., traffic zones)
poly_pop <- tracts_to_polygon(
  code_muni = 2919207,
  polygon   = nei,                          # Lauro de Freitas' neighborhoods 
  vars      = c("pop_ph", "avg_inc_resp"),
  cache         = TRUE,
  verbose       = TRUE
)


## ----fig-pop, echo=FALSE, eval=TRUE, cache=TRUE, fig.cap=paste0("Dasymetric estimates of private-household population (", cfmt("pop_ph"), ") for Lauro de Freitas, Bahia, interpolated from 2022 census tract totals to H3 hexagons at resolution~8 (left) and to neighborhoods (right) using CNEFE dwelling points as ancillary data."), fig.alt="Two side-by-side choropleth maps of Lauro de Freitas showing dasymetric estimates of private-household population. The left map shows estimates on H3 hexagons at resolution 8 and the right map shows estimates on neighborhoods. Both use a green-to-yellow colour scale where brighter yellow indicates higher population counts.", fig.width=10, fig.height=5, out.width="100%"----
library(geobr)
library(ggplot2)
library(sf)
library(dplyr)
library(patchwork)

# Lauro de Freitas boundary
muni_ldf <- geobr::read_municipality(code_muni = 2919207, year = 2020,
                                     showProgress = FALSE)

# neighborhoods of Lauro de Freitas
nei <- geobr::read_neighborhood(year = 2022, showProgress = FALSE) |>
  dplyr::filter(name_muni == "Lauro de Freitas")

# Dasymetric population to H3 hexagons at resolution 8
hex_pop <- cnefetools::tracts_to_h3(
  code_muni     = 2919207,
  h3_resolution = 8,
  vars          = "pop_ph",
  verbose       = FALSE
)

# Dasymetric population to neighborhoods
poly_pop <- cnefetools::tracts_to_polygon(
  code_muni = 2919207,
  polygon   = nei,
  vars      = "pop_ph",
  verbose   = FALSE
)

p1 <- ggplot(hex_pop) +
  geom_sf(aes(fill = pop_ph), color = NA) +
  paletteer::scale_fill_paletteer_c("grDevices::ag_GrnYl",
                                    direction = 1)+
  labs(title = "H3 resolution 8") +
  theme_void() +
  theme(plot.title = element_text(hjust = 0.5, size = 11),
        legend.position = "right",
        plot.background = element_rect(fill = "white", color = NA))

p2 <- ggplot() +
  geom_sf(data = poly_pop, aes(fill = pop_ph), color = "white",
          linewidth = 0.2) +
  paletteer::scale_fill_paletteer_c("grDevices::ag_GrnYl",direction = 1)+
  labs(title = "Neighborhoods") +
  theme_void() +
  theme(plot.title = element_text(hjust = 0.5, size = 11),
        legend.position = "right",
        plot.background = element_rect(fill = "white", color = NA))

p1 + p2


